def transform(x):
    x = abs(x)
    x = x // 2
    return x

def solve(data):
    result = tuple(transform(x) for x in data)
    return sum(result)

def transform(x):
    x = x + 1
    x = x * 2
    x = -x
    return x

def solve(data):
    result = tuple(transform(x) for x in data)
    return min(result)

def transform(x):
    x = x % 3
    x = x * 2
    x = x + 1
    return x

def solve(data):
    result = tuple(transform(x) for x in data)
    return max(result)

